local config = {
  ui_story_5055_50550101_1_dialog_content = "Selamat pagi, Eve!",
  ui_story_5055_50550101_2_dialog_content = "Hah? Biarku lihat. Ada apa dengan mata merahmu? Apakah kamu kurang tidur semalam atau bagaimana?",
  ui_story_5055_50550101_3_dialog_content = "Pak? Silakan masuk!",
  ui_story_5055_50550101_4_dialog_content = "Kamu tidak tinggal di Tail Street? Kenapa kamu datang ke sini?",
  ui_story_5055_50550101_5_dialog_content = "Apakah karena saya belum mengembalikan buku yang saya pinjam dari kamu? Saya akan selesai secepatnya dan tukar dengan buku lainnya!",
  ui_story_5055_50550101_6_dialog_content = "Hahaha, kamu benar-benar anak yang rajin dan tekun, Eve.",
  ui_story_5055_50550101_7_dialog_content = "Tapi saya di sini bukan untuk membahas buku itu. Apakah kamu ingat? Kamu harus kembali ke <color=#FFB400>dokter</color>mu hari ini.",
  ui_story_5055_50550101_8_dialog_content = "Eh? Dokter...?",
  ui_story_5055_50550101_9_dialog_content = "Oh, tidak! Hari ini aku harus pergi ke Tail Street untuk ke dokter?!",
  ui_story_5055_50550101_10_dialog_content = "Sekarang apa? Aku terlalu tidur dan lupa sama sekali... Aku akan pergi sekarang juga!",
  ui_story_5055_50550101_11_dialog_content = "Hahaha, jangan khawatir. Saya sudah bicara dengan dokter sebelum datang ke sini, dan kamu bisa pergi ke sana di siang hari.",
  ui_story_5055_50550101_12_dialog_content = "Aku membuatnya sulit untuk kamu dan dokter lagi...",
  ui_story_5055_50550101_13_dialog_content = "Tidak perlu terlalu formal denganku. Melihat kamu baik-baik saja juga membuat pikiranku tenang.",
  ui_story_5055_50550101_14_dialog_content = "Lainnya berpikir bahwa tidak layak bagi mereka untuk meluangkan waktu menangani pemulihanmu, mengingat kamu ditinggalkan dengan penyakit yang berlarut-larut setelah diserang oleh Eclipsite.",
  ui_story_5055_50550101_15_dialog_content = "Hanya dia, mengabaikan semua cemoohan dan ejekan, tetap memberikan perawatan untuk kamu...",
  ui_story_5055_50550101_16_dialog_content = "Dan sekarang, Eve kita tidak hanya <color=#FFB400>sepenuhnya pulih</color> tetapi juga menguasai Luminatics yang kuat. Siapa tahu, kamu mungkin menjadi seorang pejuang yang melindungi kerajaan kita suatu hari nanti.",
  ui_story_5055_50550101_17_dialog_content = "Dokter Anda dan saya sangat senang melihat perubahan dalam diri Anda. Tidak ada alasan bagi kami untuk menyalahkan Anda atas kesalahan kecil ini.",
  ui_story_5055_50550101_18_dialog_content = "Aku... dipulihkan? Dan aku telah menguasai Luminatics yang kuat di atas itu?",
  ui_story_5055_50550101_19_dialog_content = "Hahaha, Eve, apa kamu masih setengah tidur atau apa?",
  ui_story_5055_50550101_20_dialog_content = "Anu…",
  ui_story_5055_50550101_21_dialog_content = "Jika bukan karena kamu, siapa lagi yang akan mengawal karavan dengan aman untuk kembali dari Gurun Udara Panas?",
  ui_story_5055_50550101_22_dialog_content = "Dan siapa lagi yang bisa menyelamatkan anak-anak dari cengkeraman Eclipsites? Oh, dan—",
  ui_story_5055_50550101_23_dialog_content = "Tidak usah diungkapkan lagi, Pak. Ini hanya usaha kecil dari saya, tidak layak untuk diakui.",
  ui_story_5055_50550101_24_dialog_content = "Oh, akhirnya Eve kita kecil telah mengingat semuanya sekarang.",
  ui_story_5055_50550101_25_dialog_content = "Dokter Anda menyebutkan bahwa jika pemeriksaan hari ini berjalan baik, dia mungkin akan mengirim Anda untuk belajar di <color=#FFB400>Federasi Illumina</color>.",
  ui_story_5055_50550101_26_dialog_content = "Illumina Federation... apakah itu tempat Anda berada, Pak?",
  ui_story_5055_50550101_27_dialog_content = "Benar. Illumina Federation menawarkan pendidikan yang paling formal dan ketat dalam pengetahuan dan latihan fisik.",
  ui_story_5055_50550101_28_dialog_content = "Jika kamu mendapatkan kesempatan untuk belajar di sana, kamu pasti akan menjadi pejuang hebat, melindungi kedamaian di gurun ini.",
  ui_story_5055_50550101_29_dialog_content = "Saya percaya padamu. Tapi hei, jangan terlalu stres. Mari kita bicarakan ini setelah hasil pemeriksaanmu keluar.",
  ui_story_5055_50550101_30_dialog_content = "Jangan lupa janji temu dengan dokter kali ini. Sampai jumpa di siang hari.",
  ui_story_5055_50550101_31_dialog_content = "Terima kasih, Pak. Sampai jumpa sore ini!",
  ui_story_5055_50550101_32_dialog_content = "Mempertahankan perdamaian untuk seluruh gurun... Apakah saya benar-benar bisa melakukannya...",
  ui_story_5055_50550101_33_dialog_content = "Mari tidak terlalu jauh melangkah ke depan dan mulai dengan apa yang bisa saya lakukan sekarang.",
  ui_story_5055_50550101_33X1_dialog_content = "Suka, bersihkan ruangan!",
  ui_story_5055_50550101_34_dialog_content = "Ha! Debu kotor, bagaimana berani kamu menumpuk di kamarku?",
  ui_story_5055_50550101_35_dialog_content = "Sang prajurit hebat Eve akan membasmi kamu, tunggu saja!",
  ui_story_5055_50550101_36_dialog_content = "Dan itu juga berlaku untuk kalian Eclipsite yang mengintai di sekitar sini!",
  ui_story_5055_50550101_37_dialog_content = "Lebih baik kamu menjauh dari Jalan Warrior Eve atau kamu bahkan tidak akan hidup untuk menyesalinya!",
  ui_story_5055_50550101_38_dialog_content = "Juga... Benar, saya mendapat banyak bantuan saat sakit, jadi...",
  ui_story_5055_50550101_39_dialog_content = "Aku akan membalas mereka dengan kekuatanku dan menjadi prajurit yang benar-benar hebat!",
  ui_story_5055_50550101_40_dialog_content = "Yah, bukan berarti saya benar-benar tahu cara menjadi hebat.",
  ui_story_5055_50550101_41_dialog_content = "Tapi guru saya baru saja mengatakan bahwa Luminatics saya sangat kuat, dan saya mungkin memiliki kesempatan untuk belajar di Illumina nanti.",
  ui_story_5055_50550101_42_dialog_content = "Setelah lulus, saya yakin saya akan menjadi pejuang yang benar-benar hebat saat itu!",
  ui_story_5055_50550101_43_dialog_content = "Lalu guru saya, dokter saya, Mama, Papa, dan semua tetangga akan bangga padaku! Oh, dan...",
  ui_story_5055_50550101_44_dialog_content = "…?",
  ui_story_5055_50550101_45_dialog_content = "Dan... Aku rasa aku lupa seseorang yang <color=#FFB400>sangat penting</color>... Aku...",
  ui_story_5055_50550101_46_dialog_content = "Aduh, kepalaku sakit...",
  ui_story_5055_50550101_47_dialog_content = "Apa yang SAYA... lupa?",
  ui_story_5055_50550101_48_dialog_content = "Semakin saya mencoba mengingat, semakin kepala saya sakit...",
  ui_story_5055_50550101_49_dialog_content = "Tidak.",
  ui_story_5055_50550101_50_dialog_content = "Hah?!",
  ui_story_5055_50550101_51_dialog_content = "Jangan lupa.",
  ui_story_5055_50550101_52_dialog_content = "Jangan lupa apa? Tahu apa?",
  ui_story_5055_50550101_53_dialog_content = "...",
  ui_story_5055_50550101_54_dialog_content = "Tunggu, k-kamu bukan tetanggaku atau teman...",
  ui_story_5055_50550101_55_dialog_content = "Siapa kau?",
  ui_story_5055_50550101_56_dialog_content = "...",
  ui_story_5055_50550101_57_dialog_content = "Hei, berhenti!",
  ui_story_5055_50550102_1_dialog_content = "Huff, kenapa itu lari?",
  ui_story_5055_50550102_2_dialog_content = "Figur itu menjatuhkan sesuatu. Seharusnya ada di sekitar sini.",
  ui_story_5055_50550102_3_dialog_content = "Aha, ketemu!",
  ui_story_5055_50550102_4_dialog_content = "Aneh, kenapa semua wajah dalam gambar ini dicabik-cabik?",
  ui_story_5055_50550102_5_dialog_content = "Dan gambarnya terlihat sangat familiar... Apakah ada orang yang aku kenal yang menggambarinya?",
  ui_story_5055_50550102_6_dialog_content = "Hei, ada nama di bagian belakang buku sketsa...",
  ui_story_5055_50550102_7_dialog_content = "<color=#FFB400>Eve</color>?!",
  ui_story_5055_50550102_8_dialog_content = "Apakah ini buku sketsaku?",
  ui_story_5055_50550102_9_dialog_content = "Kapan saya menggambar ini...?",
  ui_story_5055_50550102_10_dialog_content = "Sayang sekali robekannya begitu parah.",
  ui_story_5055_50550102_11_dialog_content = "Sosok itu... Sosok itu pasti yang menghancurkan gambar!",
  ui_story_5055_50550102_12_dialog_content = "Harus mengejarnya dan mencari tahu... Tak boleh membiarkannya lolos!",
  ui_story_5055_50550501_1_dialog_content = "Heh, heh...",
  ui_story_5055_50550501_2_dialog_content = "mengerti!",
  ui_story_5055_50550501_3_dialog_content = "(Ini aneh... Sepertinya boneka beruang.)",
  ui_story_5055_50550501_4_dialog_content = "(Saya merasa pernah melihatnya di suatu tempat sebelumnya, tapi kenapa sekarang terlihat sangat menakutkan... Sayang sekali...)",
  ui_story_5055_50550501_5_dialog_content = "Kamu siapa, dan kenapa kamu merobek buku sketsaku?",
  ui_story_5055_50550501_6_dialog_content = "Bukan. Aku.",
  ui_story_5055_50550501_7_dialog_content = "Bukan kamu? Maksudmu, aku yang melakukannya dan lupa?",
  ui_story_5055_50550501_8_dialog_content = "Tapi meskipun kamu tidak merusak buku sketsa, mengapa kamu mengambilnya dan memanggil Eclipsite untuk membantu kamu?",
  ui_story_5055_50550501_9_dialog_content = "Tidak. Bukan. Aku.",
  ui_story_5055_50550501_10_dialog_content = "Anak-anak yang baik mengakui kesalahan mereka.",
  ui_story_5055_50550501_11_dialog_content = "Jika kamu tidak memberitahu saya yang sebenarnya, saya hanya bisa...",
  ui_story_5055_50550501_12_dialog_content = "Lepaskan sarung tangan anak-anak!",
  ui_story_5055_50550501_13_dialog_content = "Kamu. Bukan. Dari sini.",
  ui_story_5055_50550501_14_dialog_content = "Hei, kau. Jangan. Berada di sini.",
  ui_story_5055_50550501_15_dialog_content = "Apa? Ini adalah Gurun Rediesel. Saya lahir dan dibesarkan di sini.",
  ui_story_5055_50550501_16_dialog_content = "Evesemua orang di sini adalah temanku, jadi kenapa kamu bilang begitu?",
  ui_story_5055_50550501_17_dialog_content = "Jangan kau. Melihat.",
  ui_story_5055_50550501_18_dialog_content = "Tak usahlah. Tak ada di sini.",
  ui_story_5055_50550501_19_dialog_content = "A-Apa yang kamu lakukan?",
  ui_story_5055_50550501_20_dialog_content = "Aku akan hancurkan. Semua. <color=#FFB400>Ilusi</color> ini!",
  ui_story_5055_50550502_1_dialog_content = "Eve.",
  ui_story_5055_50550502_2_dialog_content = "(Ini tahu namaku?)",
  ui_story_5055_50550502_3_dialog_content = "(Yang lebih aneh lagi... boneka itu bisa berbicara?)",
  ui_story_5055_50550502_4_dialog_content = "(Mungkin tercemar oleh Darkflow, dilihat dari penampilannya.)",
  ui_story_5055_50550502_5_dialog_content = "(Tidak, bagaimana mungkin boneka bisa terkontaminasi?)",
  ui_story_5055_50550502_6_dialog_content = "Kau... bukan... dari sini...",
  ui_story_5055_50550502_7_dialog_content = "Kamu... jangan... di sini...",
  ui_story_5055_50550502_8_dialog_content = "(Dan mengapa itu mengatakan hal itu?)",
  ui_story_5055_50550502_9_dialog_content = "(Tidak peduli apa, apapun yang bisa memanggil Eclipsites pasti tidak baik. Saya harus memperingatkan tetangga tentang ini...)",
  ui_story_5055_50550502_10_dialog_content = "(Hei, ini tiba-tiba... menghilang?)",
  ui_story_5055_50550502_11_dialog_content = "(Sama sekali menghilang, seperti semua di sini tidak pernah ada sama sekali.)",
  ui_story_5055_50550502_12_dialog_content = "Apakah ini semua hanya halusinasi saya?",
  ui_story_5055_50550502_13_dialog_content = "Apakah Eclipsite memukul kepalaku saat mereka menyerang dulu? Saya tidak bisa mengingatnya dengan jelas sekarang...",
  ui_story_5055_50550502_14_dialog_content = "Tebak saya akan tanya dokter tentang itu di tindak lanjut siang ini.",
  ui_story_5055_50550502_15_dialog_content = "Jika memang ada masalah dengan kepala saya, apakah saya masih bisa pergi ke sekolah di Illumina?",
  ui_story_5055_50550502_16_dialog_content = "Pikiran itu membuatku panik sekarang...",
  ui_story_5055_50550502_17_dialog_content = "Tapi aku akan menghadapinya langsung! Ya!",
  ui_story_5055_50550502_18_dialog_content = "Masih ada waktu sebelum tindak lanjut, dan saya haus setelah berlari. Saya harus mendapatkan air dari sumur.",
  ui_story_5055_50550502_19_dialog_content = "Saya harus lebih berguna dan merawat rumah saya!",
  ui_story_5055_50550601_1_dialog_content = "Gurun Rediesel sangat bagus kecuali kekurangan air. Sulit bagi tanaman normal untuk tumbuh di sini.",
  ui_story_5055_50550601_2_dialog_content = "Guru saya mengatakan beberapa padang rumput dan hutan berusia ribuan tahun di luar gurun, serta lautan dengan terumbu karang dan rumput laut!",
  ui_story_5055_50550601_3_dialog_content = "Kapan ya aku bisa melihat sesuatu yang begitu cerah dan penuh semangat?",
  ui_story_5055_50550601_4_dialog_content = "\"Jelas tumbuh besar di gurun, namun sangat tertarik dengan tanaman di luar\"... Eveg guru saya bertanya-tanya darimana saya mendapatkan ketertarikan itu.",
  ui_story_5055_50550601_5_dialog_content = "Saya juga sebenarnya tidak tahu. Mayapakah itu datang secara alami?",
  ui_story_5055_50550601_6_dialog_content = "Oke, sumurnya seharusnya...",
  ui_story_5055_50550601_7_dialog_content = "Nih!",
  ui_story_5055_50550601_8_dialog_content = "EveMeskipun danau di dekat rumah itu cantik, airnya asin, jadi saya harus mendapatkan air minum dari sumur.",
  ui_story_5055_50550601_9_dialog_content = "Hampir waktunya untuk tindak lanjut.",
  ui_story_5055_50550601_10_dialog_content = "Aku harus cepat-cepat!",
  ui_story_5055_50550601_11_dialog_content = "Ups!",
  ui_story_5055_50550601_12_dialog_content = "<color=#e8d9bb>THUNK!</color>",
  ui_story_5055_50550601_13_dialog_content = "<color=#e8d9bb>Eve tersandung sesuatu, kehilangan keseimbangannya dan jatuh ke tanah.</color>",
  ui_story_5055_50550601_14_dialog_content = "Kamu...",
  ui_story_5055_50550601_15_dialog_content = "(Itu boneka lagi! Tapi bukankah sudah kalahkan? Bagaimana bisa keluar dari sumur?)",
  ui_story_5055_50550601_16_dialog_content = "(Untungnya, jatuh itu sebenarnya menyelamatkan aku dari mendekati sumur, atau aku akan terjatuh ke dalamnya.)",
  ui_story_5055_50550601_17_dialog_content = "Kau... bukan... dari sini...",
  ui_story_5055_50550601_18_dialog_content = "Kamu... jangan... berada... di sini...",
  ui_story_5055_50550601_19_dialog_content = "Bukan cara berbicara yang sama... Apakah ini boneka yang berbeda?",
  ui_story_5055_50550601_20_dialog_content = "Aku... akan membawa... kamu... keluar dari sini...",
  ui_story_5055_50550601_21_dialog_content = "Oh tidak, tidak boleh biarkan terus memanggil Eclipsites!",
  ui_story_5055_50550602_1_dialog_content = "Fiuh, itu sulit... Tapi bisa muncul lagi di tempat lain.",
  ui_story_5055_50550602_2_dialog_content = "Tapi ini pasti bukan halusinasi. Saya harus memberi tahu tetangga pastinya!",
  ui_story_5055_50550602_3_dialog_content = "Hei, apa ini di bawah kakiku?",
  ui_story_5055_50550602_4_dialog_content = "Rumput kecil?",
  ui_story_5055_50550602_5_dialog_content = "Tapi ini adalah bagian tengah dari jalan raya... Betapa gigihnya harus bertahan hidup.",
  ui_story_5055_50550602_6_dialog_content = "Tapi mengapa akarnya juga terbuka, seperti seseorang menendangnya hingga jatuh...?",
  ui_story_5055_50550602_7_dialog_content = "Tidak tersandung—saya terjatuh karena itu!",
  ui_story_5055_50550602_8_dialog_content = "Oh, rumput malang, apakah kamu memperingatkan saya untuk tidak mendekati sumur?",
  ui_story_5055_50550602_9_dialog_content = "Kamu penyelamatku, Oke!",
  ui_story_5055_50550602_10_dialog_content = "Tapi kamu tidak terlihat seperti tanaman gurun. Asalmu dari mana?",
  ui_story_5055_50550602_11_dialog_content = "Hmm, benda putih di kepalamu...",
  ui_story_5055_50550602_12_dialog_content = "Adalah... apakah ini semacam \"tumor\"?",
  ui_story_5055_50550602_13_dialog_content = "Kamu akan mengering dan mati jika mencoba tumbuh tanpa naungan di sini.",
  ui_story_5055_50550602_14_dialog_content = "Tapi jika kamu tidak keberatan, aku akan mengantarmu pulang dan memberimu air sumur yang menyegarkan!",
  ui_story_5055_50550602_15_dialog_content = "Sampai saat itu, silakan nyaman di saku saya.",
  ui_story_5055_50550701_3_dialog_content = "Ngomong-ngomong, matahari hari ini sangat menyengat.",
  ui_story_5055_50550701_4_dialog_content = "Woah!",
  ui_story_5055_50550701_5_dialog_content = "Kapan dan dari mana benda besar seperti itu berasal?!",
  ui_story_5055_50550701_6_dialog_content = "Dia... seekor kadal raksasa yang terbuat dari batang baja dan lembaran?",
  ui_story_5055_50550701_8_dialog_content = "Apakah itu peninggalan kuno yang digali dari pasir oleh salah satu tetangga?",
  ui_story_5055_50550701_9_dialog_content = "Ataukah ini merupakan inovasi baru yang ditemukan oleh Illumina?",
  ui_story_5055_50550701_11_dialog_content = "Hati-Hati! Jauhi tumpukan sampah itu!",
  ui_story_5055_50550701_12_dialog_content = "Apa? Sampah?",
  ui_story_5055_50550701_13_dialog_content = "Ya, ini hanya sekelompok sampah tak berguna—tidak tahu siapa yang membuang sampah ini di sini.",
  ui_story_5055_50550701_14_dialog_content = "Selain memakan tempat, ini juga menarik banyak <color=#FFB400>hal berbahaya</color> yang bersembunyi di dalamnya, memaksa kami untuk berpatroli di sekitar sini setiap hari.",
  ui_story_5055_50550701_15_dialog_content = "Hal berbahaya? Biar aku yang menghilangkannya!",
  ui_story_5055_50550701_16_dialog_content = "Kamu bekerja keras. Baru saja aku mengambil air dari sumur... Nah, minumlah dan tarik nafas. Bisa!",
  ui_story_5055_50550701_20_dialog_content = "...",
  ui_story_5055_50550701_21_dialog_content = "Apa? Boneka identik lainnya?",
  ui_story_5055_50550701_22_dialog_content = "Apakah boneka beruang ini bahaya yang kamu sebutkan?",
  ui_story_5055_50550701_23_dialog_content = "Hah? Apa yang kau bicarakan? Boneka? Di mana?",
  ui_story_5055_50550701_24_dialog_content = "Eh? Tapi... Jangan bilang cuma aku yang bisa melihatnya!",
  ui_story_5055_50550701_25_dialog_content = "...",
  ui_story_5055_50550701_26_dialog_content = "Bagaimanapun, tolong mundur. Boneka ini memanggil Eclipsite.",
  ui_story_5055_50550701_27_dialog_content = "Saya perlu menghilangkannya dulu!",
  ui_story_5055_50550702_1_dialog_content = "...",
  ui_story_5055_50550702_2_dialog_content = "Mengapa boneka seperti ini terus muncul hari ini...? Atau mungkin mereka mengikutiku?",
  ui_story_5055_50550702_3_dialog_content = "Tidak!!! Benda itu muncul! Kita menghadapi bahaya serius di sini!",
  ui_story_5055_50550702_4_dialog_content = "Apa? Di mana?",
  ui_story_5055_50550702_5_dialog_content = "Guk—guk! Guk, guk, guk!!",
  ui_story_5055_50550702_6_dialog_content = "Uh, itu hanya anjing.",
  ui_story_5055_50550702_7_dialog_content = "Ini bukan anjing biasa. Lihat betapa galaknya, dengan kaki depan yang dimodifikasi menjadi kuat dan kokoh...",
  ui_story_5055_50550702_8_dialog_content = "Dan bekas luka di seluruh tubuhnya... Tidak mungkin itu dari pertarungan anjing—itu pasti bekas luka dari pertempuran dengan yang lain seperti kita!",
  ui_story_5055_50550702_9_dialog_content = "Tidak ada yang mungkin tahan serangan dari anjing ini! Jadi kita harus...",
  ui_story_5055_50550702_10_dialog_content = "...Hah?",
  ui_story_5055_50550702_11_dialog_content = "Putar!",
  ui_story_5055_50550702_12_dialog_content = "Guk!",
  ui_story_5055_50550702_13_dialog_content = "Berjabat tangan!",
  ui_story_5055_50550702_14_dialog_content = "Guk!",
  ui_story_5055_50550702_15_dialog_content = "Kamu mengerti apa yang saya katakan? Anjing pintar! Biar saya menggaruk telingamu!",
  ui_story_5055_50550702_16_dialog_content = "*merengek*...",
  ui_story_5055_50550702_17_dialog_content = "Uhh...",
  ui_story_5055_50550702_18_dialog_content = "Hahaha! Anjing yang tak bisa dijinakkan siapa pun, tapi kamu berhasil mengendalikannya. Kamu memang hebat, Eve!",
  ui_story_5055_50550702_19_dialog_content = "Hewan jarang menyerang jika kita tidak mengancam mereka terlebih dahulu.",
  ui_story_5055_50550702_20_dialog_content = "Anak anjing itu bisa merasakannya jika kita tidak berniat menyakitinya.",
  ui_story_5055_50550702_21_dialog_content = "Tidak tergantung padanya apakah akan menjalani modifikasi...",
  ui_story_5055_50550702_22_dialog_content = "Mungkin ia bertindak kasar karena mencoba melindungi dirinya sendiri dan kelompoknya.",
  ui_story_5055_50550702_23_dialog_content = "*merengek*...",
  ui_story_5055_50550702_24_dialog_content = "Hahaha, rasanya geli saat kamu menjilati tanganku seperti itu...",
  ui_story_5055_50550702_25_dialog_content = "Lihat, ini anjing yang baik, dan dia tahu apa yang kita katakan!",
  ui_story_5055_50550702_26_dialog_content = "*Berdesah* Sepertinya kita terlalu berhati-hati, ya?",
  ui_story_5055_50550702_27_dialog_content = "Saya akan segera memberi tahu semua orang tentang ini agar mereka tidak secara tidak sengaja menyakitinya.",
  ui_story_5055_50550702_28_dialog_content = "Oke, doggy, kamu aman sekarang. Tak ada yang akan mencoba mengusirmu.",
  ui_story_5055_50550702_29_dialog_content = "Tapi kamu harus berjanji padaku untuk tidak menyakiti siapa pun.",
  ui_story_5055_50550702_30_dialog_content = "Hmm, kamu bisa tahu rumahku hanya dari baunya, kan?",
  ui_story_5055_50550702_31_dialog_content = "Jika kamu tidak menemukan sesuatu untuk makan, temui aku ya, oke?",
  ui_story_5055_50550702_32_dialog_content = "Guk!",
  ui_story_5055_50550702_33_dialog_content = "Ups, aku bakal telat untuk tindak lanjut dengan dokter...",
  ui_story_5055_50550702_34_dialog_content = "Oke, kamu santai saja dan aku akan segera menemuimu!",
  ui_story_5055_50550702_35_dialog_content = "*Merengek*",
  ui_story_5055_50550702_36_dialog_content = "Hei, kenapa kamu nempel di sepatuku seperti tidak ingin aku pergi?",
  ui_story_5055_50550702_37_dialog_content = "*merengek dan menggonggong*",
  ui_story_5055_50550702_38_dialog_content = "Oke, oke, aku benar-benar punya sesuatu yang sangat penting untuk dikerjakan sekarang.",
  ui_story_5055_50550702_39_dialog_content = "Aku janji padamu, aku akan kembali untukmu, dan kita bahkan bisa patroli bersama-sama!",
  ui_story_5055_50550702_40_dialog_content = "*terus merengek*",
  ui_story_5055_50550801_1_dialog_content = "(Aduh kasihan sekali anak anjing itu. Mungkin sebelumnya tidak ada yang mau mendekat, makanya dia jadi sangat lengket.)",
  ui_story_5055_50550801_2_dialog_content = "(Tidak mau menunggu di sana untukku, dan aku tidak bisa membawanya ke dokter...)",
  ui_story_5055_50550801_3_dialog_content = "(Jadi, saya harus mengambil jalan panjang untuk kehilangan itu.)",
  ui_story_5055_50550801_4_dialog_content = "(Saya merasa tidak enak tentang itu, tapi hidungnya yang tajam mungkin akan segera mengejar cukup cepat.)",
  ui_story_5055_50550801_5_dialog_content = "(Saya harus menyelesaikan pemeriksaan kesehatan sebelum itu.)",
  ui_story_5055_50550801_6_dialog_content = "Tidak! Tolong!",
  ui_story_5055_50550801_7_dialog_content = "Klinik dokter sedang terbakar! Kami butuh bantuan! Sekarang!",
  ui_story_5055_50550801_8_dialog_content = "Apa?!",
  ui_story_5055_50550801_9_dialog_content = "Dokter, profesor, di mana kau?",
  ui_story_5055_50550801_10_dialog_content = "<size=45>Dokter? Profesor? Apa kau bisa mendengarku?</size>",
  ui_story_5055_50550801_11_dialog_content = "Tolong bantu kami!",
  ui_story_5055_50550801_12_dialog_content = "Ada yang masih di dalam!",
  ui_story_5055_50550801_13_dialog_content = "Saya harus masuk!",
  ui_story_5055_50550801_14_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5055_50550801_15_dialog_content = "... Kumohon! Ada orang!",
  ui_story_5055_50550801_16_dialog_content = "Profesor, ini aku, Eve! Di mana kau?",
  ui_story_5055_50550801_17_dialog_content = "...",
  ui_story_5055_50550801_18_dialog_content = "Apa? Di sini juga?",
  ui_story_5055_50550802_1_dialog_content = "Apakah Anda baik-baik saja, Pak?",
  ui_story_5055_50550802_2_dialog_content = "Jangan mendekat!",
  ui_story_5055_50550802_3_dialog_content = "Pak? Ini saya, Eve, saya di sini untuk membantu Anda keluar.",
  ui_story_5055_50550802_4_dialog_content = "Jangan... Tolong! Tolong!",
  ui_story_5055_50550802_5_dialog_content = "Guru saya belum pernah panik seperti ini sebelumnya... Pasti ketakutan karena boneka beruang itu.",
  ui_story_5055_50550802_6_dialog_content = "Dan di mana dokternya...?",
  ui_story_5055_50550802_7_dialog_content = "Ini semua ide dia! Bukan milikku! BUKAN MILIKKU!",
  ui_story_5055_50550802_8_dialog_content = "Tolong jangan sakiti saya—!",
  ui_story_5055_50550802_9_dialog_content = "Tenang saja, Pak. Saya Eve, murid Anda. Saya tidak akan pernah menyakiti Anda!",
  ui_story_5055_50550802_10_dialog_content = "Apakah ada yang mencoba menyakiti Anda? Apakah orang itu juga membakar klinik?",
  ui_story_5055_50550802_11_dialog_content = "Itu kamu...",
  ui_story_5055_50550802_12_dialog_content = "Hah?",
  ui_story_5055_50550802_13_dialog_content = "Kamu, monster, yang menyalakan api di tempat ini!",
  ui_story_5055_50550802_14_dialog_content = "Apa...?",
  ui_story_5055_50550802_15_dialog_content = "<color=#e8d9bb>*mengeluarkan suara retak dan kresek*</color>",
  ui_story_5055_50550802_16_dialog_content = "(Api... Panas sekali...)",
  ui_story_5055_50550802_17_dialog_content = "(Di mana aku pernah melihat ini... sebelumnya...)",
  ui_story_5055_50550802_18_dialog_content = "(Sama saja... api...)",
  ui_story_5055_50550802_19_dialog_content = "(Plafonnya jatuh... Everything di sekeliling bernyanyi... Asap terlalu banyak untuk bernapas...)",
  ui_story_5055_50550802_20_dialog_content = "(Ada seseorang... di dalam api...)",
  ui_story_5055_50550802_21_dialog_content = "(Seseorang yang tak akan pernah kulupakan...)",
  ui_story_5055_50550802_22_dialog_content = "(Dia adalah...)",
  ui_story_5055_50550802_23_dialog_content = "(Dia adalah...!)",
  ui_story_5055_50550802_24_dialog_content = "Kamu rupanya! Aku tidak percaya kamu kembali.",
  ui_story_5055_50550802_25_dialog_content = "Saya di sini untuk menyelamatkan Anda, Dokter...",
  ui_story_5055_50550802_26_dialog_content = "Apakah kamu yang menyalakan api di tempat ini dan menghancurkan segala sesuatu yang telah aku kerjakan dengan susah payah untuk membangun?",
  ui_story_5055_50550802_27_dialog_content = "Tidak...",
  ui_story_5055_50550802_28_dialog_content = "Aku memberimu kekuatan yang lebih baik, tapi apa yang telah kau lakukan? Lihat kekacauan yang kau buat!",
  ui_story_5055_50550802_29_dialog_content = "Riset saya, data saya, segala yang telah saya bangun selama bertahun-tahun ini... dan bahkan tubuh ini, semuanya dilahap oleh api.",
  ui_story_5055_50550802_30_dialog_content = "Katakan padaku, Eve—dosa menghancurkan diriku! Apa yang akan kamu bayar untuk itu?",
  ui_story_5055_50550802_31_dialog_content = "<color=#e8d9bb>Bukk! *Kresek-kresek*</color>",
  ui_story_5055_50550802_32_dialog_content = "Itu bukan aku, itu bukan aku!",
  ui_story_5055_50550802_33_dialog_content = "Api...! Tapi aku ingat api itu, membakar seperti kebencian yang tak pernah padam...",
  ui_story_5055_50550802_34_dialog_content = "Mengapa kebakaran terjadi, mengapa ada kebencian dalam diriku?",
  ui_story_5055_50550802_35_dialog_content = "Saya baru saja datang ke sini untuk tindak lanjut...",
  ui_story_5055_50550802_36_dialog_content = "Saya tidak ingin menyakiti siapa pun... Saya hanya ingin menjadi Eve yang melindungi semua orang!",
  ui_story_5055_50550802_37_dialog_content = "Heheh... Ha ha ha ha!",
  ui_story_5055_50550802_38_dialog_content = "Tak punya nyali untuk mengakuinya, hah? Bukankah kamu yang mengklaim diri sebagai malaikat kecil yang sempurna?",
  ui_story_5055_50550802_39_dialog_content = "Baiklah, Kamu akan dikubur bersama dengan data risetku!",
  ui_story_5055_50550802_40_dialog_content = "Guk!",
  ui_story_5055_50550802_41_dialog_content = "Anjing merah?",
  ui_story_5055_50550802_42_dialog_content = "Tidak, jangan mendekat... Terlalu berbahaya, jangan dekat-dekat!",
  ui_story_5055_50550802_43_dialog_content = "Guk-guk!",
  ui_story_5055_50550802_44_dialog_content = "Hahaha, satu lagi yang tak sabar ingin bertemu ajalnya, hah?",
  ui_story_5055_50550802_45_dialog_content = "Baiklah! Sini! Aku sudah tidak sabar untuk mencoba belati ini!",
  ui_story_5055_50550802_46_dialog_content = "Awooo!!!",
  ui_story_5055_50550802_47_dialog_content = "Apa?!",
  ui_story_5055_50550802_48_dialog_content = "Bangunan itu runtuh... Hati-Hati!",
  ui_story_5055_50550802_49_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5055_50550802_50_dialog_content = "(Apakah saya terkubur di bawah bangunan yang runtuh?)",
  ui_story_5055_50550802_51_dialog_content = "(Jangan dengarkan dokter dan anjing lagi, hanya suara nyala api yang melahap segalanya.)",
  ui_story_5055_50550802_52_dialog_content = "Tapi aku masih bernafas...",
  ui_story_5055_50550802_53_dialog_content = "Aku masih hidup?",
  ui_story_5055_50550802_54_dialog_content = "Dari mana tanaman merambat ini berasal, dan mengapa mereka ada di sekitar aku?",
  ui_story_5055_50550802_55_dialog_content = "Ada aroma yang berbeda dari terbakar. Sebenarnya aroma itu khas dan menyenangkan.",
  ui_story_5055_50550802_56_dialog_content = "Ini aroma yang menyenangkan... Bau seperti... bunga?",
  ui_story_5055_50550802_57_dialog_content = "Aku ingat sekarang. Benda tipis, halus berwarna putih di luar tanaman merambat itu adalah bunga!",
  ui_story_5055_50550802_58_dialog_content = "Apakah itu kamu, rumput dengan tumor di sakuku?",
  ui_story_5055_50550802_59_dialog_content = "Bulb putih itu bukan tumor, tapi tunas... Bagaimana bisa aku tidak mengenalinya?",
  ui_story_5055_50550802_60_dialog_content = "Terima kasih telah menyelamatkan saya lagi.",
  ui_story_5055_50550802_61_dialog_content = "Tapi bagaimana dengan profesor, dokter, dan anak anjing merah...?",
  ui_story_5055_50550802_62_dialog_content = "Apakah karena aku...?",
  ui_story_5055_50550802_63_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5055_50550802_64_dialog_content = "Rumput, tidak! Jangan tinggalkan aku... Jangan...",
  ui_story_5055_50550802_65_dialog_content = "Kamu bodoh, kenapa mau mengorbankan diri untuk menyelamatkan aku dari api yang menyala dan bangunan yang runtuh?",
  ui_story_5055_50550802_66_dialog_content = "Jika kamu tinggal di saku saya, kamu mungkin akan berhasil dan menancapkan diri di tanah abu...",
  ui_story_5055_50550802_67_dialog_content = "Apakah saya benar-benar layak untuk pengorbanan?",
  ui_story_5055_50550802_68_dialog_content = "...",
  ui_story_5055_50550802_69_dialog_content = "Siapa di sana?",
  ui_story_5055_50550802_70_dialog_content = "?!!",
  ui_story_5055_50550802_71_dialog_content = "Apakah kamu yang menyalakan api di tempat ini dan menghancurkan segala sesuatu yang telah aku kerjakan dengan susah payah untuk membangun?",
  ui_story_5055_50550802_72_dialog_content = "Kamu, monster, yang menyalakan api di tempat ini!",
  ui_story_5055_50550802_73_dialog_content = "Apakah kamu... menyalakan kebakaran?",
  ui_story_5055_50550802_74_dialog_content = "Ya.",
  ui_story_5055_50550802_75_dialog_content = "Siapa kamu? Bagaimana bisa kamu terlihat seperti saya?",
  ui_story_5055_50550802_76_dialog_content = "Aku adalah kamu.",
  ui_story_5055_50550802_77_dialog_content = "Aku adalah rasa sakit yang kamu sembunyikan, ketakutan yang tak bisa kamu hadapi, kenangan yang kamu tolak untuk mengingat.",
  ui_story_5055_50550802_78_dialog_content = "Saya di sini untuk mengatakan jangan abaikan...",
  ui_story_5055_50550802_79_dialog_content = "Jangan abaikan kenyataan.",
  ui_story_5055_50551102_1_dialog_content = "Saya tidak pernah tahu ada tempat seperti ini di Tail Street.",
  ui_story_5055_50551102_2_dialog_content = "Apa?",
  ui_story_5055_50551102_3_dialog_content = "Di sana... Kenapa gadis itu ditahan di sana?",
  ui_story_5055_50551102_4_dialog_content = "Begitu banyak tabung dan alat yang terhubung ke tubuhnya... Kasihan sekali! Tidak adakah yang menyelamatkannya?",
  ui_story_5055_50551102_5_dialog_content = "Itu bukan sel, tetapi ruang perawatan untuk menjaga keamanan dirinya dan semua orang di sekitarnya.",
  ui_story_5055_50551102_6_dialog_content = "Ruang perawatan? Dan aku melihat boneka beruang di dalamnya!",
  ui_story_5055_50551102_7_dialog_content = "Ini mainan favoritnya dan rekan setia yang paling setia.",
  ui_story_5055_50551102_8_dialog_content = "Untuk gadis itu, tidak ada yang lebih mengenalnya daripada kamu.",
  ui_story_5055_50551102_9_dialog_content = "Aku kenal dia? Dia terlihat begitu lemah, tawar, dan wajahnya...",
  ui_story_5055_50551102_10_dialog_content = "Terlihat sama seperti milikmu!",
  ui_story_5055_50551102_11_dialog_content = "Dan tambangku juga!",
  ui_story_5055_50551102_12_dialog_content = "Itulah Eve yang sebenarnya, Eve di dunia nyata.",
  ui_story_5055_50551102_13_dialog_content = "Yang asli Eve? Maksud kamu, kita berdua ini palsu?",
  ui_story_5055_50551102_14_dialog_content = "Kami bukan palsu. Yang palsu adalah dunia tempat kita berada sekarang.",
  ui_story_5055_50551102_15_dialog_content = "Ini adalah dunia palsu yang dokter ciptakan untuk kita melalui hipnotis, dunia kebahagiaan palsu.",
  ui_story_5055_50551102_16_dialog_content = "Dia menipu kami sejak awal. Dia sama sekali tidak ingin memperlakukan kami.",
  ui_story_5055_50551102_17_dialog_content = "Dia menghapus kepribadian berlebih dalam memori kita yang dapat mengancam eksperimennya.",
  ui_story_5055_50551102_18_dialog_content = "Kemudian dia menulis ulang sejarah untuk kita, di mana orang tua kita hidup, kita disembuhkan, sehat, dan hidup bahagia selamanya.",
  ui_story_5055_50551102_19_dialog_content = "Semua untuk menjaga kami tetap waras saat dia melakukan berbagai eksperimen tidak bermoral pada kami.",
  ui_story_5055_50551102_20_dialog_content = "...",
  ui_story_5055_50551102_21_dialog_content = "Eveeskipun kami akhirnya meninggalkan dokter di belakang...",
  ui_story_5055_50551102_22_dialog_content = "Dunia ini masih mengendalikan kita, mencegah kita melihat dunia nyata.",
  ui_story_5055_50551102_23_dialog_content = "Saya sangat bahagia hidup di dunia ini... Jadi bahkan kebahagiaan itu tidak nyata?",
  ui_story_5055_50551102_24_dialog_content = "Aku tahu kamu sudah melupakan masa lalu yang tak tertahankan itu, dan itu adalah hal yang baik dari beberapa sudut pandang.",
  ui_story_5055_50551102_25_dialog_content = "Tapi kamu tidak bisa tinggal di sini. Kita harus kembali ke dunia nyata.",
  ui_story_5055_50551102_26_dialog_content = "Kembali...?",
  ui_story_5055_50551102_27_dialog_content = "Tapi saya tidak mau. Saya hanya ingin menggambar, menyiram rumput, berpatroli di luar desa, dan melindungi semua orang...",
  ui_story_5055_50551102_28_dialog_content = "Mengapa mengurungku seperti ini? Saya tidak mau, saya tidak mau!",
  ui_story_5055_50551102_29_dialog_content = "Tapi kamu harus tetap di sana atau kamu akan menghancurkan segalanya!",
  ui_story_5055_50551102_30_dialog_content = "Apakah kamu ingin tragedi yang terjadi di kampung halamanmu terulang kembali?",
  ui_story_5055_50551102_31_dialog_content = "Tragedi, kampung halaman? Apa maksudmu?",
  ui_story_5055_50551102_32_dialog_content = "Apakah kamu ingin melihat orang yang kamu cintai terluka olehmu lagi?",
  ui_story_5055_50551102_33_dialog_content = "Saudara, dan Dawn.",
  ui_story_5055_50551102_34_dialog_content = "Kakak? Saya punya kakak? Dawn...?",
  ui_story_5055_50551102_35_dialog_content = "Aduh, kepala ku sakit lagi!",
  ui_story_5055_50551102_36_dialog_content = "Aku lihat kamu masih tidak ingat.",
  ui_story_5055_50551102_37_dialog_content = "Tidak seperti kamu, saya tidak pernah berbaur dengan dunia ini, jadi saya masih ingat semua yang telah kita lalui.",
  ui_story_5055_50551102_38_dialog_content = "Mereka adalah semua yang kita miliki.",
  ui_story_5055_50551102_39_dialog_content = "Tapi kita terjebak di dunia palsu ini, tidak bisa melihat orang-orang yang benar-benar mencintai kita.",
  ui_story_5055_50551102_40_dialog_content = "Jadi, aku benci dokter yang menghapus mereka... Dan juga benci kamu!",
  ui_story_5055_50551102_41_dialog_content = "Aku benci kamu karena melupakan mereka yang pernah ada dan menerima kenyataan palsu ini dalam ketidaktahuan sepenuhnya.",
  ui_story_5055_50551102_42_dialog_content = "!!!",
  ui_story_5055_50551102_43_dialog_content = "Aku paham, aku harus membuat kamu mengingat segalanya untuk meyakinkanmu.",
  ui_story_5055_50551102_44_dialog_content = "Yuk, ikuti saya ke kampung halaman kita.",
  ui_story_5055_50551102_45_dialog_content = "Yang kita hancurkan dengan tangan kita sendiri.",
  ui_story_5055_50551102_46_dialog_content = "Kampung halaman... Tapi bukankah ini?",
  ui_story_5055_50551102_47_dialog_content = "Ikuti aku.",
  ui_story_5055_50551301_1_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5055_50551301_2_dialog_content = "Hei, apakah gunung api baru saja meletus?",
  ui_story_5055_50551301_3_dialog_content = "Benda panas yang menggelinding di seluruh tanah itu adalah lava, kan?",
  ui_story_5055_50551301_4_dialog_content = "Saya bisa merasakan satu gelombang panas demi satu, bahkan dari di sini.",
  ui_story_5055_50551301_5_dialog_content = "Apakah kita masih melanjutkan?",
  ui_story_5055_50551301_6_dialog_content = "Hampir sampai, rumah kita.",
  ui_story_5055_50551301_7_dialog_content = "Apakah rumah kita berada di dalam gunung api?",
  ui_story_5055_50551301_8_dialog_content = "Aku akan menunggumu di sebelah sana.",
  ui_story_5055_50551301_9_dialog_content = "Hei, tunggu aku!",
  ui_story_5055_50551301_10_dialog_content = "Astaga!!",
  ui_story_5055_50551301_11_dialog_content = "Ada Eclipsite bahkan di lingkungan yang sangat keras?",
  ui_story_5055_50551301_12_dialog_content = "Eclipsite ini... Mereka mengingatkan saya pada sesuatu...",
  ui_story_5055_50551301_13_dialog_content = "Hari ketika mereka menyerang desa dan menghancurkannya hingga rata dengan tanah...",
  ui_story_5055_50551301_14_dialog_content = "Dan hari ketika saya mendapatkan kekuatan mengerikan dan mengamuk seperti yang mereka lakukan.",
  ui_story_5055_50551301_15_dialog_content = "Darkflow memasuki tubuhku melalui sebuah biji kecil...",
  ui_story_5055_50551301_16_dialog_content = "Saya merasa panas dan mati rasa di dalam, seperti seratus bintang meledak dalam diam.",
  ui_story_5055_50551301_17_dialog_content = "Saya ingin kehilangan kekuatan menyiksa itu, hanya untuk menyadari bahwa itu mengangkat saya dari tanah!",
  ui_story_5055_50551301_18_dialog_content = "Saya panik ketika saya melayang di udara. Yang saya inginkan hanyalah mencengkeram dan berpegangan pada sesuatu.",
  ui_story_5055_50551301_19_dialog_content = "Saya akhirnya mengambil arus tellurik.",
  ui_story_5055_50551301_20_dialog_content = "Saya mengganggu medan magnet, menyuntikkan energi ke kerak bumi, membuat gunung api meletus, dan mengubah rumah menjadi ini...",
  ui_story_5055_50551301_21_dialog_content = "Kekuatan mengerikan itu memperbudak saya saat saya paling lemah dan tak berdaya!",
  ui_story_5055_50551301_22_dialog_content = "Saya kehilangan semua akal seperti mereka dan menghancurkan segalanya tanpa penyesalan...",
  ui_story_5055_50551301_23_dialog_content = "Apakah saya pantas hidup seperti ini?",
  ui_story_5055_50551402_1_dialog_content = "Huft, huft...",
  ui_story_5055_50551402_2_dialog_content = "Semakin sulit... dan sulit... untuk bernapas...",
  ui_story_5055_50551402_3_dialog_content = "Mengapa saya harus... melawan Eclipsite dalam kondisi seperti ini...?",
  ui_story_5055_50551402_4_dialog_content = "Saya tidak terlalu jauh sehingga tidak bisa berbalik.",
  ui_story_5055_50551402_5_dialog_content = "Namun…",
  ui_story_5055_50551402_6_dialog_content = "Haruskah saya kembali?",
  ui_story_5055_50551402_7_dialog_content = "EveDi linimasa bahagia ini telah hancur oleh api.",
  ui_story_5055_50551402_8_dialog_content = "Itu diri lain saya mengatakan tidak ada yang mengharapkan saya menjadi prajurit yang hebat dalam kenyataan.",
  ui_story_5055_50551402_9_dialog_content = "Dokter itu hanya memanfaatkan tubuhku, tetapi aku membalasnya dengan dendam yang tak terkendali.",
  ui_story_5055_50551402_10_dialog_content = "Apakah ini prospek yang harus saya hadapi?",
  ui_story_5055_50551402_11_dialog_content = "Kembali ke kenyataan yang tidak menguntungkan, penuh kebencian dan kesakitan, menahan kesepian dan siksaan dalam pengasingan.",
  ui_story_5055_50551402_12_dialog_content = "Bagaimana jika saya kehilangan kontrol lagi...?",
  ui_story_5055_50551402_13_dialog_content = "Saya mungkin melukai lebih banyak orang dan mengubah sekitar menjadi neraka seperti ini...",
  ui_story_5055_50551402_14_dialog_content = "Tidak, saya sama sekali tidak boleh membiarkan hal itu terjadi.",
  ui_story_5055_50551402_15_dialog_content = "Jika itu sifat aslinya, saya harus menghindarinya entah bagaimana!",
  ui_story_5055_50551801_1_dialog_content = "Huft, huft...",
  ui_story_5055_50551801_2_dialog_content = "Ini dia. Ini adalah kampung halaman kami...",
  ui_story_5055_50551801_3_dialog_content = "Jurang Mata Merah.",
  ui_story_5055_50551801_4_dialog_content = "Akhirnya, kamu ingat.",
  ui_story_5055_50551801_5_dialog_content = "Begitu menginjakkan kaki di sini, masa lalu kembali menghampiri saya dalam fragmen-fragmen seperti gelembung, muncul satu per satu dalam pikiran saya.",
  ui_story_5055_50551801_6_dialog_content = "Akhirnya saya menyadari kilatan penglihatan menakutkan yang datang padaku ternyata semua nyata.",
  ui_story_5055_50551801_7_dialog_content = "Ini dulunya adalah pemukiman yang mandiri, tetapi sekarang hanya ada batu-batu longgar dan tanah yang hangus...",
  ui_story_5055_50551801_8_dialog_content = "Meletusnya lava, hujan abu, retakan bumi... Semua karena aku.",
  ui_story_5055_50551801_9_dialog_content = "Ini semua gara-gara aku.",
  ui_story_5055_50551801_10_dialog_content = "Maymungkin lebih baik untukku tinggal di sini selamanya.",
  ui_story_5055_50551801_11_dialog_content = "...",
  ui_story_5055_50551801_12_dialog_content = "Kamu ingin aku kembali ke dunia nyata, kan?",
  ui_story_5055_50551801_13_dialog_content = "Tapi kamu juga tahu bahwa aku kemungkinan akan menyebabkan lebih banyak masalah bagi orang-orang di sekitarku.",
  ui_story_5055_50551801_14_dialog_content = "Jadi, apakah lebih baik untuk saya tetap di sini? Dengan begitu, diri yang sebenarnya tidak akan pernah bangun dan tidak akan pernah kehilangan kontrol...",
  ui_story_5055_50551801_15_dialog_content = "Jika kita tidak kembali, tidak ada kesempatan untuk meninggalkan ruang perawatan.",
  ui_story_5055_50551801_16_dialog_content = "Tapi aku tidak bisa mengendalikan diriku...",
  ui_story_5055_50551801_17_dialog_content = "Tidak di masa lalu, tidak sekarang, dan mungkin juga tidak di masa depan...",
  ui_story_5055_50551801_18_dialog_content = "Saya bisa menerima ketidakberdayaan dan bertahan menghadapi kenangan mengerikan itu...",
  ui_story_5055_50551801_19_dialog_content = "Tapi saya tidak bisa membiarkan orang yang mencintai saya terluka berulang kali!",
  ui_story_5055_50551801_20_dialog_content = "Jika kamu menyerah, itu akan tetap menyakiti orang-orang yang mencintai kita.",
  ui_story_5055_50551801_21_dialog_content = "Kita harus kembali.",
  ui_story_5055_50551801_22_dialog_content = "Lebih sulit menghadapi kenyataan yang keras setelah bangun dari mimpi indah.",
  ui_story_5055_50551801_23_dialog_content = "Saya tidak memiliki kemampuan untuk menahan semua kejutan itu sekaligus...",
  ui_story_5055_50551801_24_dialog_content = "Tapi aku harus berterima kasih padamu karena telah memberitahuku realitas sebenarnya dan membuatku tahu bahwa masih ada orang yang benar-benar mencintaiku.",
  ui_story_5055_50551801_25_dialog_content = "Tapi, aku... nggak bisa kembali bersamamu.",
  ui_story_5055_50551801_26_dialog_content = "Ya, kamu bisa. Kita bisa.",
  ui_story_5055_50551801_27_dialog_content = "Jika itu yang kamu inginkan, pilihan satu-satunya saya adalah...",
  ui_story_5055_50551801_28_dialog_content = "Untuk menghancurkanmu!",
  ui_story_5055_50551801_29_dialog_content = "Kamu adalah satu-satunya kunci bagi saya untuk kembali ke kenyataan. Saya bisa mengunci diri di sini selamanya jika saya bisa menghilangkan kamu.",
  ui_story_5055_50551801_30_dialog_content = "Membunuhku dan kamu tidak akan pernah melihat orang-orang yang mencintai kita lagi.",
  ui_story_5055_50551801_31_dialog_content = "Meskipun saudara saya, Dawn, dan lainnya tidak di sini, tidak apa-apa. Saya tidak memerlukan siapa pun.",
  ui_story_5055_50551801_32_dialog_content = "Saya siap untuk sendiri.",
  ui_story_5055_50551801_33_dialog_content = "Itu jauh lebih baik daripada kehilangan akal dan menghancurkan segala yang aku cintai dengan tangan sendiri...",
  ui_story_5055_50551801_34_dialog_content = "Ancaman berbahaya seperti saya seharusnya tetap tidur dan tidak bangun.",
  ui_story_5055_50551801_35_dialog_content = "Aku tahu kamu bermaksud baik. Terima kasih, tapi maaf.",
  ui_story_5055_50551801_36_dialog_content = "Aku harus membunuhmu.",
  ui_story_5055_50551801_37_dialog_content = "Aku adalah kamu. Kamu akan kehilangan kekuatanmu dengan membunuhku, dan kamu pada kenyataannya mungkin akan mati.",
  ui_story_5055_50551801_38_dialog_content = "Benarkah? Bukankah itu lebih baik, meskipun?",
  ui_story_5055_50551801_39_dialog_content = "Saya sudah sangat lelah dengan ini...",
  ui_story_5055_50551801_40_dialog_content = "Sekarang, mari kita akhiri.",
  ui_story_5055_50551802_1_dialog_content = "Akhiri itu, akhiri segalanya.",
  ui_story_5055_50551802_2_dialog_content = "Lava berhenti mengalir. Asap hitam terhenti di tengah udara. Even Eclipsite di sekitar berhenti...",
  ui_story_5055_50551802_3_dialog_content = "Sunyi sekali.",
  ui_story_5055_50551802_4_dialog_content = "Cukup untuk mendengar detak jantungku.",
  ui_story_5055_50551802_5_dialog_content = "Tapi hati saya seharusnya berhenti berdetak segera cukup.",
  ui_story_5055_50551802_6_dialog_content = "Hei, aku mendengar suara, suara sesuatu yang meledak...",
  ui_story_5055_50551802_7_dialog_content = "Ini gelembung memori yang meletus di kepala saya.",
  ui_story_5055_50551802_8_dialog_content = "Takut tak lagi, duka tak lagi, dan nyeri tak lagi...",
  ui_story_5055_50551802_9_dialog_content = "Tapi, kenapa? Kenapa air mata terus mengalir tanpa henti?",
  ui_story_5055_50551802_10_dialog_content = "Rasa sakit yang tumpul di dada saya... Apakah itu karena kekuatan yang meninggalkan saya?",
  ui_story_5055_50551802_11_dialog_content = "Ataukah ini yang mereka sebut rindu...?",
  ui_story_5055_50551802_12_dialog_content = "Saudara, Dawn... Pada akhirnya, saya masih gagal mengingat wajah kalian.",
  ui_story_5055_50551802_13_dialog_content = "Tapi aku sangat merindukanmu, dan juga yang lainnya...",
  ui_story_5055_50551802_14_dialog_content = "Jangan berpikir bahwa aku menangis karena tidak ingin meninggalkanmu. Aku... aku menangis karena...",
  ui_story_5055_50551802_15_dialog_content = "Sungguh bahagia! Akhirnya, saya melindungi kalian semua dengan cara saya sendiri!",
  ui_story_5055_50551802_16_dialog_content = "Lihat, saya tidak lupa tentang kebahagiaan. Kebahagiaan juga bisa membuat menangis.",
  ui_story_5055_50551802_17_dialog_content = "Semoga semua orang merasa bahagia untukku...",
  ui_story_5055_50551802_18_dialog_content = "Akhirnya, saya bisa pergi tanpa rasa sakit, dengan tenang, diam-diam...",
  ui_story_5055_50551802_19_dialog_content = "Ini adalah cara terbaik yang bisa saya pikirkan untuk membalas cinta Anda.",
  ui_story_5055_50551802_20_dialog_content = "...",
  ui_story_5055_50551802_21_dialog_content = "<color=#e8d9bb>*Gruk*</color>",
  ui_story_5055_50551802_22_dialog_content = "Ada apa?",
  ui_story_5055_50551802_23_dialog_content = "<size=45><color=#e8d9bb>Gemuruh!</color></size>",
  ui_story_5055_50551802_24_dialog_content = "Eveemua menghilang, bahkan kekuatanku, jadi tidak ada yang seharusnya mempengaruhi kenyataan ini...",
  ui_story_5055_50551802_25_dialog_content = "Kecuali…",
  ui_story_5055_50551802_26_dialog_content = "Kecuali jika diri yang sebenarnya sedang sekarat.",
  ui_story_5055_50551802_27_dialog_content = "Jangan sia-siakan usaha Anda untuk menyelamatkan saya, silahkan...",
  ui_story_5055_50551802_28_dialog_content = "Cukup biarkan aku pergi...",
  ui_story_5055_50551802_29_dialog_content = "Tidak, kamu masih hidup dan harus terus hidup!",
  ui_story_5055_50551802_30_dialog_content = "Siapa ini?",
  ui_story_5055_50551802_31_dialog_content = "Kamu tidak ingat aku, Eve? Ini PlayerName. Aku PlayerName!",
  ui_story_5055_50551802_32_dialog_content = "PlayerName? Saya pernah mendengar cerita tentang Pangeran Pharming yang menyelamatkan seorang putri yang koma... Apakah kamu Pangeran Tampanku?",
  ui_story_5055_50551802_33_dialog_content = "Tapi kamu tidak perlu mengungkit masa laluku, karena bahkan aku tahu...",
  ui_story_5055_50551802_34_dialog_content = "Seseorang seperti saya tidak layak diselamatkan...",
  ui_story_5055_50551802_35_dialog_content = "Tapi kami benar-benar membutuhkan bantuan Anda!",
  ui_story_5055_50551802_36_dialog_content = "Bantuan saya? Apa yang bisa saya lakukan?",
  ui_story_5055_50551802_37_dialog_content = "Kamu bisa melakukan lebih dari yang kamu bayangkan!",
  ui_story_5055_50551802_38_dialog_content = "Tapi kekuatanku jahat dan tak terkendali. Aku akan menghancurkan segalanya...",
  ui_story_5055_50551802_39_dialog_content = "Baik dokter maupun Eclipsites tidak memaksa itu padamu!",
  ui_story_5055_50551802_40_dialog_content = "Ini adalah kemampuan alami yang selama ini terpendam di dalam dirimu!",
  ui_story_5055_50551802_41_dialog_content = "Ini cukup kuat untuk melindungi kita semua!",
  ui_story_5055_50551802_42_dialog_content = "Ingatlah sumber kekuatanmu yang sebenarnya!",
  ui_story_5055_50551802_43_dialog_content = "Kami semua menunggu kamu kembali...",
  ui_story_5055_50551802_44_dialog_content = "<size=45>Bangun!</size>",
  ui_story_5055_50551802_45_dialog_content = "<size=45>Bangun!</size> BANGUN! <size=30>Bangun...</size>",
  ui_story_5055_50551901_1_dialog_content = "...",
  ui_story_5055_50551901_2_dialog_content = "Mengerti... Akhirnya saya menemukan potongan yang hilang!",
  ui_story_5055_50551901_3_dialog_content = "Inilah orang-orang yang paling penting bagiku...",
  ui_story_5055_50551901_4_dialog_content = "Sekarang saatnya menggabungkan potret semua orang!",
  ui_story_5055_50551901_5_dialog_content = "Apakah ini bisa...",
  ui_story_5055_50551901_6_dialog_content = "Hmm, layak untuk dicoba.",
  ui_story_5055_50551901_7_dialog_content = "...",
  ui_story_5055_50551901_8_dialog_content = "Hei, ini adalah...",
  ui_story_5055_50551901_9_dialog_content = "Sinsa... Dawn... PlayerName...!",
  ui_story_5055_50551901_10_dialog_content = "Semua wajah mereka! Akhirnya saya ingat bagaimana semua wajah mereka.",
  ui_story_5055_50551901_11_dialog_content = "Apa yang terjadi, mengapa hari ini aku tidak bisa mengontrol air mataku...",
  ui_story_5055_50551901_12_dialog_content = "Aku paham, sebenarnya aku ingin bertemu setiap orang lebih dari yang kubayangkan.",
  ui_story_5055_50551901_13_dialog_content = "Saya pikir saya sudah memutuskan untuk tinggal di sini sekali untuk selamanya...",
  ui_story_5055_50551901_14_dialog_content = "Tidak, kamu ingin keluar, bangun, dan pergi jalan-jalan dengan outfit terbaikmu.",
  ui_story_5055_50551901_15_dialog_content = "Kamu bisa mengunjungi padang rumput yang penuh dengan bunga, atau hutan hujan yang subur.",
  ui_story_5055_50551901_16_dialog_content = "Saya pikir kekuatan saya telah mengubah saya menjadi monster yang hanya akan menyakiti orang...",
  ui_story_5055_50551901_17_dialog_content = "Tidak, kamu akan melindungi kami dengan kekuatanmu.",
  ui_story_5055_50551901_18_dialog_content = "Selama kamu memercayai orang yang bisa kamu jadi. Kehebatan dan kemuliaannya akan menjadi masa depanmu.",
  ui_story_5055_50551901_19_dialog_content = "Saya pikir jika saya menjauh dari semua orang dan sendirian, saya tidak akan menimbulkan masalah...",
  ui_story_5055_50551901_20_dialog_content = "Tidak, kamu tidak pernah sendirian.",
  ui_story_5055_50551901_21_dialog_content = "EveSetiap orang ada di sini sepanjang waktu.",
  ui_story_5055_50551901_22_dialog_content = "Eve!",
  ui_story_5055_50551901_23_dialog_content = "Eve…",
  ui_story_5055_50551901_24_dialog_content = "Eve, Eve, Eve...",
  ui_story_5055_50551901_25_dialog_content = "Eve!",
  ui_story_5055_50551901_26_dialog_content = "Kakak…",
  ui_story_5055_50551901_27_dialog_content = "Keluarga saya, teman-teman saya, kerinduan saya akan dunia nyata...",
  ui_story_5055_50551901_28_dialog_content = "Saya mendapatkannya kembali, mendapatkan semuanya kembali!",
  ui_story_5055_50551901_29_dialog_content = "Tapi aku saat ini belum lengkap. Aku telah menghancurkan bagian dari diriku.",
  ui_story_5055_50551901_30_dialog_content = "Aku tak bisa pergi dan bertemu kamu lagi...",
  ui_story_5055_50551901_31_dialog_content = "Ya, kamu bisa. Kamu selalu bisa.",
  ui_story_5055_50551901_32_dialog_content = "Hah?",
  ui_story_5055_50551901_33_dialog_content = "Kau kembali! Aku pikir kamu benar-benar pergi!",
  ui_story_5055_50551901_34_dialog_content = "Kamu bisa merasa takut lagi, bukan?",
  ui_story_5055_50551901_35_dialog_content = "Setelah apa yang telah aku lakukan padamu... Terima kasih sudah kembali padaku.",
  ui_story_5055_50551901_36_dialog_content = "Tapi aku paham bahwa aku tak pernah bisa menghilangkan kecemasan dan ketakutan ku.",
  ui_story_5055_50551901_37_dialog_content = "Haruskah saya bersyukur karena tidak bisa mengalahkan mereka?",
  ui_story_5055_50551901_38_dialog_content = "Kamu tidak hanya takut kehilangan kendali atas kekuatanmu, kamu juga takut pada banyak hal lainnya.",
  ui_story_5055_50551901_39_dialog_content = "Serangga yang menggigit, sengat yang tajam, tempat gelap, saudara terluka, tidak ada yang memperhatikan kamu...",
  ui_story_5055_50551901_40_dialog_content = "Berhenti, cukup berhenti! Haruskah kamu terus berlanjut?",
  ui_story_5055_50551901_41_dialog_content = "Tapi tak apa-apa. Itu yang membuatmu jadi dirimu... Dirimu yang sebenarnya, kita yang sebenarnya.",
  ui_story_5055_50551901_42_dialog_content = "Hanya mereka yang mengerti cinta dan memiliki sesuatu untuk dicintai yang bisa merasakan takut dan duka.",
  ui_story_5055_50551901_43_dialog_content = "Kekuatan yang saya miliki sekarang berasal dari cinta di hati Anda.",
  ui_story_5055_50551901_44_dialog_content = "Kamu pergi lagi?",
  ui_story_5055_50551901_45_dialog_content = "Aku adalah kamu. Aku bagian dari kita. Aku takkan pernah pergi.",
  ui_story_5055_50551901_46_dialog_content = "Tapi aku akan menjadi dirimu, mengubah kita menjadi aku dan memberimu kekuatan untuk maju ke depan.",
  ui_story_5055_50551901_47_dialog_content = "Bisakah kita... Bisakah saya keluar dari sini sekarang?",
  ui_story_5055_50551901_48_dialog_content = "Ya. Kita akan bangun di dunia nyata sebentar lagi.",
  ui_story_5055_50551901_49_dialog_content = "Aku punya pertanyaan lain! PlayerName bilang mereka butuh bantuan ku.",
  ui_story_5055_50551901_50_dialog_content = "Kamu tahu kenyataannya lebih baik daripada saya, jadi beri tahu saya bagaimana saya bisa membantu setelah saya bangun?",
  ui_story_5055_50551901_51_dialog_content = "Kamu sudah membantu mengendalikan badai. Tapi ada satu hal yang diinginkan semua orang darimu.",
  ui_story_5055_50551901_52_dialog_content = "Mereka ingin kamu menjalani hidup yang bahagia dan bebas kekhawatiran.",
  ui_story_5055_50551901_53_dialog_content = "Tidak masalah jika kamu belum dewasa, belum cukup kuat, atau memerlukan banyak latihan untuk menguasai kekuatanmu.",
  ui_story_5055_50551901_54_dialog_content = "Kuncinya adalah untuk bertahan dan hidup.",
  ui_story_5055_50551901_55_dialog_content = "Bangun! Eve!",
  ui_story_5055_50551901_56_dialog_content = "Dengar, ada seseorang yang menunggumu.",
  ui_story_5055_50551901_57_dialog_content = "Itu PlayerName, sobat, Dawn, dan para Rediesel Wrench...",
  ui_story_5055_50551901_58_dialog_content = "Mereka butuh saya!",
  ui_story_5055_50551901_59_dialog_content = "Saya takut akan banyak hal di dunia nyata di luar sana, tetapi ada banyak hal yang saya cintai juga!",
  ui_story_5055_50551901_60_dialog_content = "Cinta jauh lebih berharga daripada kebencian.",
  ui_story_5055_50551901_61_dialog_content = "Saya punya orang yang saya cintai, tempat yang saya cintai, jadi...",
  ui_story_5055_50551901_62_dialog_content = "Aku akan terus hidup!",
  ui_story_5055_50551901_63_dialog_content = "Sangat segera, aku akan membuka mataku...",
  ui_story_5055_50551901_64_dialog_content = "Kemudian, aku akan mengambil nafas pertamaku dengan segala yang aku miliki dan menghargai hidupku.",
  ui_story_5055_50551901_65_dialog_content = "Aku akan hidup, begitu juga mereka yang mencintaiku!",
  ui_story_5055_50559901_1_dialog_content = "Potongan ini...",
  ui_story_5055_50559901_2_dialog_content = "<color=#e8d9bb>Sepertinya kertas ini sobekan dari sebuah buku bergambar.</color>",
  ui_story_5055_50559901_3_dialog_content = "<color=#e8d9bb>Secara samar-samar menggambarkan kepala seorang wanita misterius yang mengenakan jas putih.</color>",
  ui_story_5055_50559901_4_dialog_content = "Bukankah ini bagian yang hilang dari buku bergambar saya! Bentuknya cocok... tapi mengapa warnanya terlihat aneh...?",
  ui_story_5055_50559901_5_dialog_content = "Biarkan saya lihat apa yang ada di dalamnya...",
  ui_story_5055_50559901_6_dialog_content = "Ini dokter saya!",
  ui_story_5055_50559901_7_dialog_content = "Ini dokter baik yang menyembuhkan saya! Hehe, ya, itu masuk akal.",
  ui_story_5055_50559901_8_dialog_content = "Setelah semua, ini semua berkat dia aku bebas sekarang. Aku pasti ingin berterima kasih padanya karena telah memberiku rumah yang begitu bahagia.",
  ui_story_5055_50559901_9_dialog_content = "Kalau dipikir-pikir, aku bahkan tidak ingat apakah dia pernah tersenyum. Saya pikir dia sangat ketat atau memiliki kualitas yang agak aneh tentang dirinya.",
  ui_story_5055_50559901_10_dialog_content = "Hei, apakah itu yang mereka sebut... ironi?",
  ui_story_5055_50559901_11_dialog_content = "Tapi rasanya dia pasti pernah tersenyum padaku setidaknya sekali...",
  ui_story_5055_50559901_12_dialog_content = "Eh, kenapa tiba-tiba terasa dingin di sini di padang pasir... Aku harus mencari bagian lain selagi aku bisa!",
  ui_story_5055_50559901_13_dialog_content = "Tunggu saja sampai saya tangkap siapa pun yang merobek buku bergambar ini! Tidak bisa percaya mereka benar-benar merobek wajah dokter! Ada apa dengan mereka?!",
  ui_story_5055_50559901_14_dialog_content = "Mereka merobeknya begitu parah sehingga saya bahkan tidak bisa memasangnya kembali...",
  ui_story_5055_50559901_15_dialog_content = "Tunggu sebentar, sekarang setelah saya melihat sobekan ini dengan benar, sepertinya ada barisan bekas gigitan gigi di sini...",
  ui_story_5055_50559901_16_dialog_content = "Mungkinkah itu bukan bayangan tapi sejenis makhluk yang menggerogoti bagian ini?",
  ui_story_5055_50559901_17_dialog_content = "Erm, tapi jika itu hanya makhluk, maka aku akan menjatuhkannya. Aku tidak bisa mengejar hewan...",
  ui_story_5055_50559902_1_dialog_content = "<color=#e8d9bb>Pada lembaran kertas terdapat gambar pot bunga keramik yang berisi gundukan tanah kecil.</color>",
  ui_story_5055_50559902_2_dialog_content = "Ini selembar kertas dengan pot bunga kosong di atasnya... Persis sama dengan yang saya miliki di rumah!",
  ui_story_5055_50559902_3_dialog_content = "Kecuali yang ini kosong... Tidak ada yang tumbuh di dalamnya.",
  ui_story_5055_50559902_4_dialog_content = "Seandainya saja aku punya benih yang tepat untuk itu...",
  ui_story_5055_50559902_5_dialog_content = "Apakah kertas ini juga sobekan dari buku bergambar milikku?",
  ui_story_5055_50559902_6_dialog_content = "Sepertinya ukurannya sudah pas, tetapi gambarnya salah semua.",
  ui_story_5055_50559902_7_dialog_content = "Seharusnya ada wajah seseorang yang penting bagiku di sini...",
  ui_story_5055_50559902_8_dialog_content = "Tapi aku tidak ingat apa-apa. Kepalaku kosong seperti pot bunga ini!",
  ui_story_5055_50559902_9_dialog_content = "Melupakan orang-orang yang paling penting bagiku... itu seperti pot bunga yang kehilangan bunganya.",
  ui_story_5055_50559902_10_dialog_content = "Semua yang perlu saya lakukan adalah memikirkan cara untuk menemukan apa yang sedang saya cari...",
  ui_story_5055_50559903_1_dialog_content = "<color=#e8d9bb>Makhluk putih misterius!</color>",
  ui_story_5055_50559903_2_dialog_content = "Uh—Benda apa ini? Saya belum pernah melihat katak putih sebelumnya!",
  ui_story_5055_50559903_3_dialog_content = "Saya sangat menyukai katak, dan yang berwarna putih seperti ini pasti sangat langka!",
  ui_story_5055_50559903_4_dialog_content = "Hmm... tapi sepertinya ini tidak terlalu mirip katak—ukurannya kecil dan indah sekali. Maymungkin ini sebenarnya seekor kodok...",
  ui_story_5055_50559903_5_dialog_content = "Kamu salah jalan, kodok kecil, danaunya ke arah sana! Melompat-lompat di Gurun Rediesel terlalu lama dan Anda bisa mengering.",
  ui_story_5055_50559903_6_dialog_content = "Aku tahu tempat lain di mana ada air, jika kamu tidak keberatan untuk ikut denganku...",
  ui_story_5055_50559903_7_dialog_content = "Sejujurnya, kenapa kamu mau datang ke tempat yang kering dan gelap seperti ini...?",
  ui_story_5055_50559903_8_dialog_content = "... Untuk menemukan... Eve...",
  ui_story_5055_50559903_9_dialog_content = "?!",
  ui_story_5055_50559903_10_dialog_content = "Apakah aku mendengar sesuatu tadi... Apakah itu hanya imajinasiku?",
  ui_story_5055_50559904_1_dialog_content = "<color=#e8d9bb>Mainan dengan penampilan yang khas. Meskipun desain dasarnya tampak cukup biasa, ia memiliki keunggulan pengerjaan yang sangat indah.</color>",
  ui_story_5055_50559904_2_dialog_content = "Mainan ini... tampak seperti anjing berbulu merah itu...",
  ui_story_5055_50559904_3_dialog_content = "... Apakah kamu datang ke sini untuk bergabung denganku di tempat anjing itu?",
  ui_story_5055_50559904_4_dialog_content = "Sedikit kotor, tapi memegangnya membuatku merasa hangat di dalam, seperti memeluk seseorang yang dekat denganku...",
  ui_story_5055_50559904_5_dialog_content = "Aku tiba-tiba merasa sedikit rindu rumah.",
  ui_story_5055_50559904_6_dialog_content = "Ini aneh, bukankah rumahku benar-benar dekat?",
  ui_story_5055_50559904_7_dialog_content = "Tapi mengapa aku masih merindukan keluarga ku sangat...?",
  ui_story_5055_50559904_8_dialog_content = "Aku merindukan saat-saat tangan besar dan hangat itu memelukku...",
  ui_story_5055_50559905_1_dialog_content = "<color=#e8d9bb>Item yang ditinggalkan oleh makhluk putih!</color>",
  ui_story_5055_50559905_2_dialog_content = "Saya pikir saya melihat makhluk kecil yang pucat melompat di depan saya baru saja...",
  ui_story_5055_50559905_3_dialog_content = "Apakah itu meninggalkan ini?",
  ui_story_5055_50559905_4_dialog_content = "Sungguh harta kecil yang indah! Coba saya lihat, apakah ini hairband super kecil?",
  ui_story_5055_50559905_5_dialog_content = "Sepertinya agak familiar... Di mana ya pernah kulihat ini sebelumnya...?",
  ui_story_5055_50559905_6_dialog_content = "Aku di sini... Eve...",
  ui_story_5055_50559905_7_dialog_content = "Saya benar-benar mendengar sesuatu! Tapi rasanya seperti datang dari tempat yang aneh...",
  ui_story_5055_50559905_8_dialog_content = "Seperti... ada seseorang yang memanggilku dari dalam...",
  ui_story_5055_50559906_1_dialog_content = "<color=#e8d9bb>Selembar kertas dengan pola kunci pas kolosal, memancarkan aura kekuatan dan gaya.</color>",
  ui_story_5055_50559906_2_dialog_content = "... Apa ini... lukisanku yang lain? Yang ini terlihat seperti kunci pas.",
  ui_story_5055_50559906_3_dialog_content = "Aku ingat saat kakakku memberiku kuas lukis pertamaku... Hal pertama yang dia ajarkan untuk melukis adalah kunci inggris ini.",
  ui_story_5055_50559906_4_dialog_content = "Dia sangat marah pada dirinya sendiri ketika lukisannya tidak sesuai dengan yang diinginkan, jadi dia menggulung halaman itu dengan kesal...",
  ui_story_5055_50559906_5_dialog_content = "Tapi ketika saya melukis satu yang lebih baik daripada miliknya, dia terlihat sangat bangga dan mengatakan bahwa dia tidak heran saya bisa melakukannya, mengingat saya adalah saudarinya.",
  ui_story_5055_50559906_6_dialog_content = "...",
  ui_story_5055_50559906_7_dialog_content = "... Kakak...",
  ui_story_5055_50559907_1_dialog_content = "<color=#e8d9bb>Sebuah benih yang kesepian, seperti sumpah yang khidmat, menunggu untuk ditemukan di sudut.</color>",
  ui_story_5055_50559907_2_dialog_content = "Apakah ini... benih bunga?!",
  ui_story_5055_50559907_3_dialog_content = "Saya ingat seperti apa bunga-bunga Anda!",
  ui_story_5055_50559907_4_dialog_content = "Ini benihmu, kan? Teman kecil yang hilang dalam kebakaran...",
  ui_story_5055_50559907_5_dialog_content = "Terima kasih. Kamu selalu ada saat aku sangat membutuhkanmu.",
  ui_story_5055_50559907_6_dialog_content = "Tapi apa yang kamu lakukan di tempat seperti ini?! Kamu bisa terbakar!",
  ui_story_5055_50559907_7_dialog_content = "Biarkan aku memberimu rumah baru—tempat di mana aku bisa menjagamu dengan aman! Aku tidak akan membiarkan hal buruk terjadi padamu, aku janji!",
  ui_story_5055_50559907_8_dialog_content = "Saya pikir, dulu sekali, saya membuat janji lain...",
  ui_story_5055_50559907_9_dialog_content = "Saya harus ingat!",
  ui_story_5055_50559908_1_dialog_content = "<color=#e8d9bb>Letakkan ikat rambut kecil pada makhluk putih kecil itu!</color>",
  ui_story_5055_50559908_2_dialog_content = "<color=#e8d9bb>Katak itu tampaknya menjadi lebih besar setelah ikat rambut diletakkan di atasnya, dan mulai memancarkan cahaya redup.</color>",
  ui_story_5055_50559908_3_dialog_content = "Ini cocok sempurna! Ini mungkin hanya aksesoris kecil yang sederhana...",
  ui_story_5055_50559908_4_dialog_content = "Tapi itu agak membuat kamu terlihat lebih diperhalus, seperti pangeran katak dalam buku gambar dongeng itu.",
  ui_story_5055_50559908_5_dialog_content = "(Saya yakin jika saya mendandaninya dengan benar, itu akan menjadi pangeran yang tampan!)",
  ui_story_5055_50559908_6_dialog_content = "Hei, kemana kamu pikir kamu pergi?!",
  ui_story_5055_50559908_7_dialog_content = "Tidak aman di luar sana! Jangan pergi!",
  ui_story_5055_50559908_8_dialog_content = "Jangan khawatir. Aku tahu kamu tidak akan pernah menyakitiku.",
  ui_story_5055_50559908_9_dialog_content = "Apa?!",
  ui_story_5055_50559908_10_dialog_content = "... Perjuanganmu... sangat sulit. Biarkan aku melakukan sesuatu untukmu juga!",
  ui_story_5055_50559908_11_dialog_content = "Agar kamu tidak harus menjalani semua ini sendirian!",
  ui_story_5055_50559909_1_dialog_content = "<color=#e8d9bb>Makhluk putih kecil itu Colossus!</color>",
  ui_story_5055_50559909_2_dialog_content = "Ini adalah... Aku ingat! Terbang melintasi langit, megah dan bebas...",
  ui_story_5055_50559909_3_dialog_content = "Pernahkah saya berada di dalamnya?",
  ui_story_5055_50559909_4_dialog_content = "... Aku ingat jendela yang bersinar, dengan luas biru yang dalam di luar.",
  ui_story_5055_50559909_5_dialog_content = "Aku ingat seseorang memberiku makanan dan mengucapkan kata-kata baik padaku.",
  ui_story_5055_50559909_6_dialog_content = "Saya mulai berlari di sekitar tempat ini... Sudah lama sekali saya tidak merasa sebahagia itu, dan kemudian...",
  ui_story_5055_50559909_7_dialog_content = "Uh—",
  ui_story_5055_50559909_8_dialog_content = "Kemudian kamu memulai perjalanan.",
  ui_story_5055_50559909_9_dialog_content = "Kamu—?!",
  ui_story_5055_50559909_10_dialog_content = "Meskipun kamu menghadapi banyak petualangan tak terduga di sepanjang perjalanan, kamu bertekad untuk memenuhi janji penting.",
  ui_story_5055_50559909_11_dialog_content = "... Sekarang, kamu akhirnya sangat dekat untuk memenuhi janji itu, dan ada banyak orang yang menunggu kamu...",
  ui_story_5055_50559910_1_dialog_content = "<color=#e8d9bb>Mainan itu melihat kunci inggris dalam lukisan dan melompat ke halaman yang robek dengan antusiasme yang tak terkendali.</color>",
  ui_story_5055_50559910_2_dialog_content = "<color=#e8d9bb>Mainan dan kunci pas memancarkan cahaya hangat, seperti sinar matahari pagi. Eve mengusap matanya, dan wajah yang familiar muncul dalam gambar.</color>",
  ui_story_5055_50559910_3_dialog_content = "Ah! Dia... Dia saudara laki-laki saya!",
  ui_story_5055_50559910_4_dialog_content = "Akhirnya... Akhirnya saya ingat wajah saudara laki-laki saya!",
  ui_story_5055_50559910_5_dialog_content = "... E... Eve!",
  ui_story_5055_50559910_6_dialog_content = "... Suara adikku! Darimana asalnya...?",
  ui_story_5055_50559910_7_dialog_content = "Keinginan terbakarnya telah terwujud. Meskipun kamu bisa mendengar suaranya, dia tidak bisa merasakan kehadiranmu.",
  ui_story_5055_50559910_8_dialog_content = "Eve!",
  ui_story_5055_50559910_9_dialog_content = "Aku minta maaf untuk semua yang terjadi sebelumnya. Aku tidak cukup memperhatikan perasaanmu yang sebenarnya... karena kupikir aku melindungimu, tapi... Aku tidak mengerti betapa sakitnya dirimu...",
  ui_story_5055_50559910_10_dialog_content = "Saya kakak yang buruk.",
  ui_story_5055_50559910_11_dialog_content = "Tidak, saudara, saya sangat keras kepala. Aku hanya... Aku tidak tahan dengan keadaanku lagi. Itu sebabnya...",
  ui_story_5055_50559910_12_dialog_content = "Badai akan datang, tapi jangan khawatir—saya janji akan melindungi kamu.",
  ui_story_5055_50559910_13_dialog_content = "TIDAK... Sinsa, lari saja, cepat...",
  ui_story_5055_50559910_14_dialog_content = "Aku akan membuat lubang di badai ini dengan tanganku dan menyeretmu keluar dari sana! Aku akan membawamu pulang!",
  ui_story_5055_50559910_15_dialog_content = "Kemudian, jika Anda pikir Anda bisa memaafkan saya suatu hari nanti, bangun saja ...",
  ui_story_5055_50559910_16_dialog_content = "... Rumah tetap seperti saat kamu tinggalkan. Semua boneka kesukaanmu dan lukisanmu menunggu di kamarmu...",
  ui_story_5055_50559910_17_dialog_content = "...",
  ui_story_5055_50559910_18_dialog_content = "Eve, aku benar-benar merindukanmu...",
  ui_story_5055_50559910_19_dialog_content = "... Sinsa... Aku juga merindukanmu...",
  ui_story_5055_50559911_1_dialog_content = "<color=#e8d9bb>Sebuah benih bunga jatuh ke dalam pot kosong dalam buku bergambar, dan bunga fajar mekar di halaman.</color>",
  ui_story_5055_50559911_2_dialog_content = "<color=#e8d9bb>Bunga mekar dengan cahaya yang bersinar, secerah fajar. Eve mengusap matanya, dan wajah yang familiar muncul di halaman.</color>",
  ui_story_5055_50559911_3_dialog_content = "Dawn! Aku... Aku ingat! Ini wajah temanku—yang selalu ada untukku... Ini Dawn!",
  ui_story_5055_50559911_4_dialog_content = "... Eve.",
  ui_story_5055_50559911_5_dialog_content = "... Suara siapa itu? Dawn... Dawn! Apakah itu kamu?",
  ui_story_5055_50559911_6_dialog_content = "Keinginan terbakarnya telah terwujud. Kamu bisa mendengar suaranya, tetapi kata-katamu tidak bisa tersampaikan kepadanya.",
  ui_story_5055_50559911_7_dialog_content = "... Eve...",
  ui_story_5055_50559911_8_dialog_content = "... Melihatmu seperti ini... Ini mengingatkanku pada hari kita bertemu...",
  ui_story_5055_50559911_9_dialog_content = "Di rumah sakit yang dingin itu, tubuh kami ditutupi oleh sensor dan tabung...",
  ui_story_5055_50559911_10_dialog_content = "Saya... Saya tidak seandal yang kamu pikirkan...",
  ui_story_5055_50559911_11_dialog_content = "Dalam kegelapan, dan melalui ketakutan, yang bisa kulakukan hanyalah menggenggam ototku dan bersiap untuk nyeri... Itulah mengapa dulu aku mengabaikanmu, dan mengapa kamu hampir salah mengerti.",
  ui_story_5055_50559911_12_dialog_content = "Tidak, kamu ITU bisa diandalkan, Dawn! Dan kamu adalah orang paling berani yang aku tahu...",
  ui_story_5055_50559911_13_dialog_content = "Rumah sakit itu seperti sangkar, dan kamu adalah satu-satunya yang berani menantang penculik kita secara langsung.",
  ui_story_5055_50559911_14_dialog_content = "Tak lama setelah itu, saya menyadari bahwa kamu sama sekali tidak buruk—kamu hanya suka menatap orang dengan tatapan tajam di wajahmu.",
  ui_story_5055_50559911_15_dialog_content = "Sepenuhnya, sama sekali, tidak mengerikan.",
  ui_story_5055_50559911_16_dialog_content = "... Aku sangat suka mendengarkan cerita-ceritamu. Suaramu, kata-katamu... Mereka menyampaikan keindahan dunia yang aku rindukan dan menggambarkannya di depan mataku.",
  ui_story_5055_50559911_17_dialog_content = "... Meskipun agak canggung ketika kamu lupa apa yang seharusnya datang selanjutnya...",
  ui_story_5055_50559911_18_dialog_content = "Tapi cerita-cerita itu sendiri tidak pernah sepenting hanya memiliki kamu di sisiku...",
  ui_story_5055_50559911_19_dialog_content = "Kamu memberi air pada bunga, kamu memberi nama untukku...",
  ui_story_5055_50559911_20_dialog_content = "Saya sangat suka nama ini... Dawn... Dawn...",
  ui_story_5055_50559911_21_dialog_content = "Jadi, kamu harus bangun segera, oke?",
  ui_story_5055_50559911_22_dialog_content = "Ingat janji yang kita buat—untuk menyaksikan saat bunga fajar mekar, bersama-sama...",
  ui_story_5055_50559911_23_dialog_content = "Dawn, aku masih ingat... aku ingat segalanya... *menangis* Itu sangat mengerikan.",
  ui_story_5055_50559911_24_dialog_content = "Dawn masih berdiri di sana di ladang bunga fajar menunggu saya untuk menemukannya!",
  ui_story_5055_50559912_1_dialog_content = "<color=#e8d9bb>Putra katak putih melompat ke dalam gambar dan duduk tegak di atas Colossus.</color>",
  ui_story_5055_50559912_2_dialog_content = "<color=#e8d9bb>Sayap putih Colossus meluas membentuk lengkungan, seperti hujan meteor yang mencapai cakrawala. Eve menggosok matanya, dan wajah yang familiar muncul di halaman.</color>",
  ui_story_5055_50559912_3_dialog_content = "Aku tahu kamu!",
  ui_story_5055_50559912_4_dialog_content = "Tail Street, Eclipsites, Saudara, Dawn, dan orang-orang yang menghadapi kenangan ini bersamaku...",
  ui_story_5055_50559912_5_dialog_content = "PlayerName, aku ingat kamu!",
  ui_story_5055_50559912_6_dialog_content = "Ini kamu sepanjang waktu, terus berbicara padaku, mendorongku maju melalui mimpi ini dengan informasi dari dunia luar...",
  ui_story_5055_50559912_7_dialog_content = "Menemani aku saat menyaring masa lalu untuk menemukan rasa sakit, kemarahan, ketakutan dalam diriku...",
  ui_story_5055_50559912_8_dialog_content = "Even jika setiap orang dikutuk di bagian terdalam mimpi yang terpelintir ini...",
  ui_story_5055_50559912_9_dialog_content = "Di mana saudara laki-laki telah berubah menjadi anjing besar, Dawn telah berubah menjadi bunga, dan penyihir jahat mengubah kamu menjadi seekor kodok kecil...",
  ui_story_5055_50559912_10_dialog_content = "Kamu masih menemukanku! Kamu tidak bisa membiarkanku menghadapi mimpi buruk ini sendirian!",
  ui_story_5055_50559912_11_dialog_content = "Kamu adalah pangeran kodokku, bukan?",
  ui_story_5055_50559912_12_dialog_content = "... Jika itu benar, izinkan saya bertanya sesuatu.",
  ui_story_5055_50559912_13_dialog_content = "Kenangan kacau Anda telah diredakan, dan kutukan pangeran Anda telah diangkat.",
  ui_story_5055_50559912_14_dialog_content = "Tentu saja putri ingin bebas dari kutukan penyihir dan menghadapi jati dirinya yang sebenarnya juga, kan?",
  ui_story_5055_50559912_15_dialog_content = "Diriku yang sebenarnya...",
  ui_story_5055_50559912_16_dialog_content = "Katakan padaku, apa yang paling kamu inginkan sekarang ini?",
  ui_story_5055_50559912_17_dialog_content = "Ingin ketemu kamu!",
  ui_story_5055_50559912_18_dialog_content = "Saya ingin melihat Dawn dan saudara laki-laki saya! Saya ingin melihat Vice dan setiap orang yang telah merawat saya di Rediesel Wrench!",
  ui_story_5055_50559912_19_dialog_content = "Aku merindukan kalian semua... Maymeskipun mungkin belum terlalu lama bagi kalian di sana.",
  ui_story_5055_50559912_20_dialog_content = "Tapi rasanya aku sendirian di sini sudah sangat lama!",
  ui_story_5055_50559912_21_dialog_content = "PlayerName, bisakah kamu membawaku kembali bersamamu?",
  ui_story_5055_50559912_22_dialog_content = "Kekuatanmu akan memandu kamu kembali.",
  ui_story_5055_50559912_23_dialog_content = "Tunggu... Kamu meninggalkan aku?",
  ui_story_5055_50559912_24_dialog_content = "(Jangan lupa... cintamu.)"
}
return config
